CREATE SELECTIVE XML INDEX sxi3 ON docs (xcol) FOR (p1 = '/order/id' AS XQUERY 'xs:double');

CREATE SPATIAL INDEX six3 ON places (geog) USING GEOGRAPHY_AUTO_GRID WITH (CELLS_PER_OBJECT = 12, DATA_COMPRESSION = NONE);
